import { Injectable } from '@angular/core';
import { Observable, of, throwError } from 'rxjs';

interface User {
  email: string;
  password: string;
  role?:string;
}

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  constructor() {}

  login(user: User): Observable<any> {
    const users: User[] = [
      { email: 'admin@example.com', password: 'admin123', role: 'admin' },
      { email: 'customer@example.com', password: 'cust123', role: 'customer' }
    ];

    const matchedUser = users.find(u => u.email === user.email && u.password === user.password);

    if (matchedUser) {
      return of({ message: 'Login successful', role: matchedUser.role });
    } else {
      return throwError(() => new Error('Invalid credentials'));
    }
  }

  register(user: User): Observable<any> {
    // Simulate successful registration
    return of({ message: 'Registration successful' });
  }

  forgotPassword(email: string): Observable<any> {
    // Simulate password reset logic
    const emails = ['admin@example.com', 'customer@example.com'];
    if (emails.includes(email)) {
      return of({ message: 'Reset link sent to email' });
    } else {
      return throwError(() => new Error('Email not found'));
    }
  }
}
